<script setup lang="ts">
import { SUB_TRANSITIONS, transitionError, type SubStatus } from '@brightloop/shared'
import type { Row } from '~/utils/resources'
const props=defineProps<{portal?:boolean}>(),route=useRoute(),api=useApi(),toast=useToast()
const endpoint=computed(()=>`${props.portal?'/portal/billing':''}/subscriptions/${route.params.id}`)
const {data:sub,error,status,refresh}=await useFetch<Row>(()=>'/api'+endpoint.value)
const busy=ref(false)
const transitions=computed(()=>sub.value?(SUB_TRANSITIONS[sub.value.status as SubStatus]||[]).filter(to=>!transitionError(sub.value!.status,to,sub.value!.plan)):[])
async function action(kind:string,value?:string){busy.value=true;try{let path=endpoint.value+'/'+kind;let body:Row={};if(props.portal){path=endpoint.value+'/action';body={action:value||kind}}else if(kind==='transition')body={to:value};const result=await api<Row>(path,{method:'POST',body});toast.add({title:'Updated successfully',color:'success'});if(kind==='invoice'&&result.id)await navigateTo(`/invoices/${result.id}`);else await refresh()}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=false}}
</script>
<template><div class="page"><UAlert v-if="error" color="error" :title="errorMessage(error)"/><USkeleton v-if="status==='pending'" class="h-64"/><template v-if="sub"><div class="page-head"><div><UButton :to="portal?'/portal/billing':'/subscriptions'" variant="link" icon="i-lucide-arrow-left" class="px-0 mb-2">{{portal?'Billing':'Subscriptions'}}</UButton><h1>{{sub.number}}</h1><p>{{sub.customer.name}} · {{sub.plan.name}}</p></div><UBadge size="lg" variant="subtle">{{sub.status}}</UBadge></div><div class="flex flex-wrap gap-2 mb-6 no-print"><template v-if="!portal"><UButton v-for="to in transitions" :key="to" :loading="busy" variant="soft" @click="action('transition',to)">Move to {{to.toLowerCase()}}</UButton><UButton v-if="sub.status==='ACTIVE'" :loading="busy" @click="action('invoice')">Create invoice</UButton><UButton v-if="['DRAFT','QUOTATION'].includes(sub.status)" :to="`/subscriptions/${sub.id}/edit`" color="neutral" variant="outline">Edit</UButton></template><template v-else><UButton v-if="sub.status==='QUOTATION'" :loading="busy" @click="action('action','accept')">Accept quotation</UButton><UButton v-if="sub.status==='ACTIVE'&&sub.plan.pausable" :loading="busy" variant="soft" @click="action('action','pause')">Pause</UButton><UButton v-if="sub.status==='PAUSED'" :loading="busy" @click="action('action','resume')">Resume</UButton><UButton v-if="['ACTIVE','PAUSED'].includes(sub.status)&&sub.plan.closable" :loading="busy" color="neutral" variant="outline" @click="action('action','close')">Close subscription</UButton></template><UButton v-if="['ACTIVE','PAUSED'].includes(sub.status)&&sub.plan.renewable&&sub.expiryDate" :loading="busy" variant="outline" @click="action('renew')">Renew</UButton></div><div class="grid sm:grid-cols-3 gap-4 mb-6"><UCard><p class="text-sm text-muted">Monthly recurring revenue</p><p class="text-2xl font-semibold mt-2">{{money(sub.mrr)}}</p></UCard><UCard><p class="text-sm text-muted">Started</p><p class="text-xl mt-2">{{date(sub.startDate)}}</p></UCard><UCard><p class="text-sm text-muted">Expiry</p><p class="text-xl mt-2">{{date(sub.expiryDate)}}</p></UCard></div><UCard class="mb-6"><template #header><h2 class="font-semibold">Next invoice preview</h2></template><div v-if="sub.nextInvoice"><p class="text-sm text-muted mb-4">{{date(sub.nextInvoice.periodStart)}} – {{date(sub.nextInvoice.periodEnd)}}</p><div v-for="line in sub.nextInvoice.lines" :key="line.productId" class="flex justify-between gap-4 py-3 border-b border-default"><div>{{line.description}} <span class="text-muted">× {{line.quantity}}</span><p v-if="line.discount" class="text-xs text-success mt-1">Discount {{money(line.discount)}} · {{line.discountNames.join(', ')}}</p></div><span>{{money(line.total)}}</span></div><div class="flex justify-end gap-10 mt-5 font-semibold"><span>Total including tax</span><span>{{money(sub.nextInvoice.total)}}</span></div></div><p v-else class="text-muted">No further invoices scheduled.</p></UCard><UCard><template #header><h2 class="font-semibold">Invoice history</h2></template><p v-if="!sub.invoices.length" class="text-muted py-5">Invoices will appear after the first billing run.</p><NuxtLink v-for="inv in sub.invoices" :key="inv.id" :to="`${portal?'/portal/billing':''}/invoices/${inv.id}`" class="flex justify-between py-4 border-b border-default"><span class="text-primary">{{inv.number}}</span><span>{{inv.status}} · {{money(inv.total)}}</span></NuxtLink></UCard><UCard v-if="sub.timeline?.length" class="mt-6"><template #header><h2 class="font-semibold">Activity</h2></template><div v-for="entry in sub.timeline" :key="entry.id" class="border-l-2 border-primary/30 pl-4 pb-5"><p class="text-sm font-medium">{{entry.action}}</p><p class="text-xs text-muted mt-1">{{entry.detail}} · {{date(entry.at)}}</p></div></UCard></template></div></template>
